const { useEffect, useRef, useState } = React;

const SCHEMES = ["normal", "light", "dark", "light dark", "only light", "only dark"];

// 浏览器最终采用的方案：normal 按亮色渲染，light dark 跟随系统偏好，only 只是禁止强制深色
const resolveScheme = (scheme, systemDark) => {
  if (scheme === "light dark") return systemDark ? "dark" : "light";
  if (scheme.endsWith("dark")) return "dark";
  return "light";
};

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

const Component = () => {
  const stageRef = useRef(null);
  const [scheme, setScheme] = useState("light dark");
  const [systemDark, setSystemDark] = useState(false);
  const [canvas, setCanvas] = useState("");

  // 订阅系统颜色偏好，light dark 的实际结果随之变化
  useEffect(() => {
    const query = window.matchMedia?.("(prefers-color-scheme: dark)");
    if (!query) return;
    const update = () => setSystemDark(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  // 读出系统颜色 Canvas 在当前方案下映射到的实际色值
  useEffect(() => {
    setCanvas(getComputedStyle(stageRef.current).backgroundColor);
  }, [scheme, systemDark]);

  const resolved = resolveScheme(scheme, systemDark);
  const forcedDark = scheme.startsWith("only") ? "禁止" : "允许";

  return (
    <div className="@container flex flex-col gap-3">
      <style>{`
        @scope {
          /* 应用的样式重置会抹掉原生控件外观，这里退回浏览器默认样式 */
          .cb-native :where(input, select, button, progress) { all: revert; }
        }
      `}</style>
      <div className="flex flex-wrap items-center gap-2">
        {SCHEMES.map(value => (
          <Choice key={value} active={scheme === value} onClick={() => setScheme(value)}>
            {value}
          </Choice>
        ))}
      </div>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,38%)]">
        <div
          ref={stageRef}
          className="cb-native flex min-w-0 flex-col gap-3 rounded-tau-md border border-line-1 p-4 transition-colors"
          style={{ colorScheme: scheme, background: "Canvas", color: "CanvasText" }}
        >
          <p className="m-0 text-tau-body">
            背景是 <code className="font-tau-mono">Canvas</code>，文字是{" "}
            <code className="font-tau-mono">CanvasText</code>，选中这段文字看看高亮色。
          </p>
          <div className="flex flex-wrap items-center gap-3">
            <input type="text" placeholder="文本框" size={10} />
            <select>
              <option>选项一</option>
              <option>选项二</option>
            </select>
            <button type="button">按钮</button>
          </div>
          <div className="flex flex-wrap items-center gap-4 text-tau-body">
            <label className="flex items-center gap-1.5">
              <input type="checkbox" defaultChecked />
              复选框
            </label>
            <label className="flex items-center gap-1.5">
              <input type="radio" name="cb-scheme-radio" defaultChecked />
              单选
            </label>
            <input type="range" />
            <progress value={60} max={100} />
          </div>
          <div className="h-16 overflow-y-scroll border px-2 py-1 text-tau-sm" style={{ borderColor: "GrayText" }}>
            {Array.from({ length: 8 }, (_, index) => (
              <div key={index}>滚动条也由浏览器绘制，第 {index + 1} 行</div>
            ))}
          </div>
          <a href="#" onClick={event => event.preventDefault()} className="text-tau-body underline" style={{ color: "LinkText" }}>
            链接颜色 LinkText
          </a>
        </div>
        <dl className="m-0 grid h-fit grid-cols-[auto_minmax(0,1fr)] gap-x-4 gap-y-2 rounded-tau-md bg-hover px-3 py-2.5 text-tau-sm">
          <dt className="text-ink-3">声明值</dt>
          <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">color-scheme: {scheme}</dd>
          <dt className="text-ink-3">系统偏好</dt>
          <dd className="m-0 font-tau-mono text-ink-1">{systemDark ? "dark" : "light"}</dd>
          <dt className="text-ink-3">实际方案</dt>
          <dd className="m-0">
            <span className={`rounded-tau-sm px-1.5 py-0.5 font-tau-mono ${resolved === "dark" ? "bg-accent-soft text-accent-text" : "bg-surface text-ink-1"}`}>
              {resolved}
            </span>
          </dd>
          <dt className="text-ink-3">强制深色</dt>
          <dd className="m-0 text-ink-1">{forcedDark}</dd>
          <dt className="text-ink-3">Canvas</dt>
          <dd className="m-0 min-w-0 break-all font-tau-mono text-ink-1">{canvas || "—"}</dd>
        </dl>
      </div>
    </div>
  );
};

