const { useEffect, useState } = React;

const SCHEMES = ["light", "dark", "light dark"];
const LIGHT_BG = "linear-gradient(135deg, #ffffff, #f3f4f6)";
const DARK_BG = "linear-gradient(135deg, #1f2937, #111827)";
// 每条声明的两个分支：第一个用于亮色，第二个用于暗色
const RULES = [
  { selector: ".area", prop: "background", onLight: LIGHT_BG, onDark: DARK_BG },
  { selector: ".area", prop: "color", onLight: "#333333", onDark: "#eeeeee" },
  { selector: ".link", prop: "color", onLight: "blue", onDark: "lightblue" },
];

const STYLE = `
  @scope {
    .cb-area {
      background: light-dark(${LIGHT_BG}, ${DARK_BG});
      color: light-dark(#333333, #eeeeee);
      transition: color 300ms var(--tau-ease-out);
    }
    .cb-link { color: light-dark(blue, lightblue); }
    .cb-native :where(input, select, button) { all: revert; }
  }
`;

const Choice = ({ active, onClick, children }) => (
  <button
    type="button"
    aria-pressed={active}
    onClick={onClick}
    className={`cursor-pointer rounded-tau-sm border px-2.5 py-1 font-tau-mono text-tau-sm transition-colors ${
      active ? "border-accent bg-accent-soft text-accent-text" : "border-line-1 bg-surface text-ink-2 hover:bg-hover"
    }`}
  >
    {children}
  </button>
);

// light-dark() 的一个参数：命中的分支高亮，另一个淡出
const Branch = ({ value, active }) => (
  <span
    className={`inline-flex items-center gap-1 rounded-tau-sm px-1 transition-colors ${
      active ? "bg-accent-soft text-accent-text" : "text-ink-3 opacity-60"
    }`}
  >
    <span className="inline-block size-2.5 shrink-0 rounded-full border border-line-1" style={{ background: value }} />
    {value}
  </span>
);

const Component = () => {
  const [scheme, setScheme] = useState("light");
  const [systemDark, setSystemDark] = useState(false);

  useEffect(() => {
    const query = window.matchMedia?.("(prefers-color-scheme: dark)");
    if (!query) return;
    const update = () => setSystemDark(query.matches);
    update();
    query.addEventListener("change", update);
    return () => query.removeEventListener("change", update);
  }, []);

  const isDarkScheme = scheme === "dark" || (scheme === "light dark" && systemDark);
  const resolved = isDarkScheme ? "dark" : "light";

  return (
    <div className="@container flex flex-col gap-3">
      <style>{STYLE}</style>
      <div className="flex flex-wrap items-center gap-2">
        <span className="text-tau-sm text-ink-3">color-scheme</span>
        {SCHEMES.map(value => (
          <Choice key={value} active={scheme === value} onClick={() => setScheme(value)}>
            {value}
          </Choice>
        ))}
        <span className="ml-auto text-tau-sm text-ink-3">
          当前方案：<span className="font-tau-mono text-ink-1">{resolved}</span>
        </span>
      </div>
      <div className="grid gap-3 @lg:grid-cols-[minmax(0,1fr)_minmax(240px,42%)]">
        <div
          className="cb-area cb-native flex min-h-[200px] min-w-0 flex-col justify-between gap-4 rounded-tau-md border border-line-1 p-4"
          style={{ colorScheme: scheme }}
        >
          <div className="flex flex-col gap-1.5">
            <span className="text-tau-title">.area</span>
            <p className="m-0 text-tau-body">背景渐变与文字颜色都写在 light-dark() 里，随方案切换。</p>
            <a href="#" onClick={event => event.preventDefault()} className="cb-link w-fit text-tau-body underline">
              .link 链接颜色
            </a>
          </div>
          <div className="flex flex-wrap items-center gap-3 text-tau-body">
            <input type="text" placeholder="原生输入框" size={10} />
            <label className="flex items-center gap-1.5">
              <input type="checkbox" defaultChecked />
              原生复选框
            </label>
          </div>
        </div>
        <pre className="m-0 flex min-w-0 flex-col gap-2 whitespace-pre-wrap break-all rounded-tau-md border border-line-1 bg-surface p-3 font-tau-mono text-tau-sm leading-[1.7] text-ink-2">
          <div>
            <span className="text-accent-text">:root</span> {"{"} color-scheme: {scheme}; {"}"}
          </div>
          {RULES.map(rule => (
            <div key={`${rule.selector}-${rule.prop}`}>
              <span className="text-accent-text">{rule.selector}</span> {"{"} {rule.prop}: light-dark(
              <Branch value={rule.onLight} active={!isDarkScheme} />,{" "}
              <Branch value={rule.onDark} active={isDarkScheme} />); {"}"}
            </div>
          ))}
        </pre>
      </div>
    </div>
  );
};
